html:
{%- set co = frappe.db.get_single_value("Weighbridge Settings", "report_company_name") or "Rajdatta Agro Industry" -%}
{%- set addr = frappe.db.get_single_value("Weighbridge Settings", "report_address") or "" -%}
{%- set ph = frappe.db.get_single_value("Weighbridge Settings", "report_phone") or "" -%}
{%- set fd = "dd/MM/yyyy" -%}
<script>document.title = "{{ doc.name }}";</script>
<style>
@font-face { font-family: "SlipDeva"; font-weight: normal; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Regular.ttf") format("truetype"); }
@font-face { font-family: "SlipDeva"; font-weight: bold; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Bold.ttf") format("truetype"); }
.wbp, .wbp td, .wbp th, .wbp div, .wbp p, .wbp h2, .wbp h3 { font-family: "SlipDeva", "Noto Sans Devanagari", sans-serif; color: #111; }
.wbp { font-size: 12.5px; line-height: 1.45; }
.wbp table { width: 100%; border-collapse: collapse; }
.wbp td, .wbp th { padding: 4px 6px; border: 1px solid #555; vertical-align: top; }
.wbp th { background: #e8edf5; text-align: center; }
.wbp .head { text-align: center; border-bottom: 2px solid #0b2a5b; padding-bottom: 6px; margin-bottom: 8px; }
.wbp .head h2 { margin: 2px 0; font-size: 20px; color: #0b2a5b; }
.wbp .head .ad { font-size: 11px; color: #333; }
.wbp .title { text-align: center; font-size: 15px; font-weight: bold; margin: 6px 0 8px; text-decoration: underline; }
.wbp .r { text-align: right; } .wbp .c { text-align: center; } .wbp .b { font-weight: bold; }
.wbp .lab { background: #f3f5f9; font-weight: bold; white-space: nowrap; }
.wbp .sp { height: 8px; }
.wbp .sign td { border: none; padding-top: 46px; text-align: center; }
.wbp .tot td { font-weight: bold; background: #f3f5f9; }
.wbp .words { margin-top: 6px; }
</style>
<div class="wbp">
 <div class="head">
  <img src="/assets/vyavantra_weighbridge/images/rajdatt_logo.png" style="height:46px"><br>
  <h2>{{ co }}</h2>
  <div class="ad">{{ addr }}{% if ph %} &nbsp;|&nbsp; फोन: {{ ph }}{% endif %}</div>
 </div>

 <div class="title">वजन पावती</div>
 <table>
  <tr><td class="lab">पावती क्र.</td><td>{{ doc.name }}</td><td class="lab">अनुक्रमांक</td><td>{{ doc.serial_no or "" }}</td></tr>
  <tr><td class="lab">दिनांक</td><td>{{ frappe.utils.formatdate(doc.slip_date, fd) }}</td><td class="lab">वेळ / शिफ्ट</td><td>{{ doc.get_formatted("slip_time") if doc.slip_time else "" }} / {{ doc.shift or "" }}</td></tr>
  <tr><td class="lab">वाहन क्र.</td><td>{{ doc.vehicle }} {{ doc.trolley_type or "" }}</td><td class="lab">पुरवठा प्रकार</td><td>{{ {"Farmer Cane": "शेतकरी ऊस", "Farm Delivery": "फार्म डिलिव्हरी", "Gate Cane": "गेट केन", "Harvesting Machine": "हार्वेस्टिंग मशीन"}.get(doc.delivery_type, doc.delivery_type or "") }}</td></tr>
  <tr><td class="lab">ऊस पुरवठादार</td><td>{{ doc.farmer }} - {{ doc.farmer_name }}</td><td class="lab">गाव / अंतर</td><td>{{ doc.village or "" }} ({{ doc.distance or 0 }} कि.मी.)</td></tr>
  <tr><td class="lab">ऊस प्रकार / जात</td><td>{{ doc.cane_type or "" }} / {{ doc.variety or "" }}</td><td class="lab">एजंट</td><td>{{ doc.agent or "" }}</td></tr>
  <tr><td class="lab">वाहतूक ठेकेदार</td><td>{{ doc.transport_contractor or "" }}</td><td class="lab">तोडणी ठेकेदार</td><td>{{ doc.cutting_contractor or "" }}</td></tr>
 </table>
 <div class="sp"></div>
 <table>
  <tr><td class="lab">एकूण (भरलेले) वजन</td><td class="r">{{ "%.2f"|format(doc.gross_weight or 0) }} किलो</td></tr>
  <tr><td class="lab">वाहनाचे (रिकामे) वजन</td><td class="r">{{ "%.2f"|format(doc.tare_weight or 0) }} किलो</td></tr>
  <tr><td class="lab">ऊस वजन</td><td class="r">{{ "%.2f"|format(doc.cane_weight or 0) }} किलो</td></tr>
  <tr><td class="lab">मॅट वजन</td><td class="r">{{ "%.2f"|format(doc.mat_weight or 0) }} किलो</td></tr>
  <tr><td class="lab">इतर कपात {% if doc.deduction_reason %}({{ doc.deduction_reason }}){% endif %}</td><td class="r">{{ "%.2f"|format(doc.other_deduction or 0) }} किलो</td></tr>
  <tr class="tot"><td style="font-size:14px">निव्वळ ऊस वजन</td><td class="r" style="font-size:14px">{{ "%.2f"|format(doc.net_cane_weight or 0) }} किलो &nbsp;({{ "%.3f"|format((doc.net_cane_weight or 0) / 1000) }} मे. टन)</td></tr>
 </table>
 {% if doc.amended_from %}<p><b>पुन्हा वजन / दुरुस्ती:</b> {{ doc.correction_reason }}</p>{% endif %}
 <table class="sign"><tr><td>वजनकाटा ऑपरेटर</td><td>ड्रायव्हर / शेतकरी</td></tr></table>
</div>
